def block_quote(self, token: Dict[str, Any], state: BlockState) -> str:
    text = self.render_children(token, state)
    lines = text.splitlines(True)
    if not lines:
        return ''
    quoted_lines = []
    for line in lines:
        if line.strip():
            quoted_lines.append('> ' + line)
        else:
            quoted_lines.append(line)
    return ''.join(quoted_lines) + '\n\n'
